#!/usr/bin/env bash
#
# run-bun-tests.sh — прогон бэкендового набора с собственным сторожем времени.
#
# Что случилось. С 19.09.2026 джоба «Test suite baseline» регулярно падала не
# красными тестами, а тишиной: `bun test --max-concurrency 1 --isolate`
# замолкал на произвольном файле и стоял так до потолка джобы (15 минут),
# после чего Actions писал «The operation was canceled» и убивал осиротевший
# bun. Ни одного упавшего теста в логе при этом нет — то есть по логу это
# выглядит как «набор красный», хотя набор не добежал.
#
# Что это на самом деле. Зависание не про конкретную ветку и не про конкретный
# тест: за сутки оно поймало пять прогонов на пяти разных ветках и на РАЗНЫХ
# файлах (conflict-markers-gate — трижды, svg-render-dimensions,
# backup-native-db). Общего у этих файлов одно: рядом с ними родится
# подпроцесс (bash из гейта, воркер рендера, tar из бэкапа). Флаг `--isolate`
# в bun 1.3.14 — это «каждому файлу свежий global, утёкшие ручки не переезжают
# в следующий файл», то есть между файлами есть шаг сборки мусора по ручкам;
# он и встаёт намертво рядом с блокирующим spawn. Починить это в нашем коде
# нельзя: баг в рантайме, а `--isolate` нам нужен (без него текут слушатели
# Bun.serve({ port: 0 }) из мини-аппа — ради этого флаг и появился).
#
# Что делает скрипт. Ставит зависанию СВОЙ срок, заметно меньше потолка джобы,
# и на нём перезапускает прогон. Разница с потолком Actions принципиальная:
#   - 15 минут молчания превращаются в 5 с явным сообщением, где именно встало;
#   - вторая попытка идёт в той же джобе, а не «перезапустите руками»;
#   - красные тесты НЕ перезапускаются: повтор лечит зависание рантайма, а
#     флаки-тест он бы прятал. Дошедший до конца прогон отдаётся как есть.
# Если зависли обе попытки — это уже не шум рантайма, и скрипт закрывается
# кодом 124, а не молчанием.
#
# Срок считается от последнего вывода, а не от старта. Это важно: здоровый
# набор идёт 5,5–9 минут, и «срок от старта» рубил бы его наравне с зависшим —
# гейт начал бы врать ровно там, где его чинили. Признак жизни один и дешёвый:
# файл вывода растёт.
#
# Usage: .github/scripts/run-bun-tests.sh <output-file>
#   (запускать из каталога agent — там же, где раньше стоял инлайн)
#
# Env (для тестов; в CI значения по умолчанию):
#   BUN_TEST_TIMEOUT_SEC  сколько терпеть ТИШИНУ прогона (default 300)
#   BUN_TEST_ATTEMPTS     сколько попыток всего (default 2)
#   BUN_TEST_POLL_SEC     шаг опроса сторожа (default 1)
#
# Exit codes: 0 — ок; код bun — если прогон дошёл до конца; 124 — все попытки
# зависли; 2 — ошибка вызова.

set -uo pipefail

OUTPUT_FILE="${1:-}"
if [ -z "$OUTPUT_FILE" ]; then
  echo "::error::run-bun-tests: не передан файл для вывода bun test." >&2
  exit 2
fi

# Пустая строка из окружения — это не «значение задано»: тот же nonblank, что
# в deploy-lock.sh, и по той же причине.
nonblank() {
  local raw="${1-}" fallback="${2-}"
  if [ -z "${raw//[[:space:]]/}" ]; then printf '%s' "$fallback"; else printf '%s' "$raw"; fi
}

LIMIT="$(nonblank "${BUN_TEST_TIMEOUT_SEC-}" "300")"
ATTEMPTS="$(nonblank "${BUN_TEST_ATTEMPTS-}" "2")"
POLL="$(nonblank "${BUN_TEST_POLL_SEC-}" "1")"

# Команда одна на весь файл: менять набор флагов надо здесь, а не в YAML, где
# её уже однажды потеряли. `--max-concurrency 1 --isolate` — см. шапку.
BUN_ARGS=(test --max-concurrency 1 --isolate)

# Где встало. Для отчёта берём последнюю группу файла и хвост вывода: по ним
# видно, на каком тесте рантайм замолчал, — иначе зависание неотличимо от
# зависания в любом другом месте, и следующий такой случай снова начнут
# расследовать с нуля.
report_where() {
  local last
  # Без якоря на начало строки: убитый прогон обрывается на полуслове, и
  # последняя группа нередко оказывается приклеена к хвосту предыдущей.
  last="$(grep -aoE '##\[group\][^ ]*\.test\.ts:' "$OUTPUT_FILE" 2>/dev/null | tail -1)"
  last="$(nonblank "${last#\#\#\[group\]}" "(групп в выводе нет)")"
  echo "::warning::run-bun-tests: прогон молчал ${LIMIT}s, последний файл: ${last%:}" >&2
  echo "--- последние 15 строк вывода ---" >&2
  tail -15 "$OUTPUT_FILE" >&2 || true
}

# 0 — прогон дошёл до конца (код bun в BUN_CODE), 1 — прогон завис и убит.
BUN_CODE=0
run_once() {
  : > "$OUTPUT_FILE"
  # Вывод через tee, а не редиректом: в Actions лог должен идти живым, иначе
  # при зависании на экране вообще ничего нет. $! при этом — pid самого bun,
  # а не tee, что сторожу и нужно.
  bun "${BUN_ARGS[@]}" > >(tee "$OUTPUT_FILE") 2>&1 &
  local pid=$! quiet_since=$SECONDS seen="" now
  while kill -0 "$pid" 2>/dev/null; do
    # Срок — это ТИШИНА, а не общая длительность. Разница не косметическая:
    # здоровый набор идёт 5,5–9 минут, и срок «от старта» убивал бы его вместе
    # с зависшим — гейт начал бы врать ровно там, где его чинили. Признак
    # жизни — рост файла вывода: между тестами bun печатает непрерывно, а
    # зависший рантайм не пишет ничего (в CI вывод идёт блоками, поэтому
    # смотрим именно размер, а не каждую строку).
    now="$(wc -c < "$OUTPUT_FILE" 2>/dev/null || echo 0)"
    now="${now//[[:space:]]/}"
    if [ "$now" != "$seen" ]; then
      seen="$now"
      quiet_since=$SECONDS
    fi
    # Время меряем часами шелла, а не числом шагов: шаг опроса дробный, и
    # «сколько мы уже ждём» из него получается только с накоплением ошибки.
    if [ $((SECONDS - quiet_since)) -ge "$LIMIT" ]; then
      kill -KILL "$pid" 2>/dev/null || true
      wait "$pid" 2>/dev/null
      sleep 0.3  # дать tee дописать файл, прежде чем его читает report_where
      return 1
    fi
    sleep "$POLL"
  done
  wait "$pid"
  BUN_CODE=$?
  return 0
}

attempt=1
while [ "$attempt" -le "$ATTEMPTS" ]; do
  echo "run-bun-tests: попытка $attempt из $ATTEMPTS (срок ${LIMIT}s)."
  if run_once; then
    if [ "$BUN_CODE" != "0" ]; then
      # Прогон дошёл до конца и покраснел — это ответ по существу, повторять
      # его нельзя: повтор красных тестов прячет флаки и удваивает время.
      echo "run-bun-tests: прогон завершился сам, код $BUN_CODE — повтора не будет."
    fi
    exit "$BUN_CODE"
  fi
  report_where
  attempt=$((attempt + 1))
done

echo "::error::run-bun-tests: набор замолчал ${ATTEMPTS} раза подряд на ${LIMIT}s. Это уже не шум рантайма — смотрите последний файл выше." >&2
exit 124
